// Set at build time by `vite.config.ts` (`define`).

/** The app's version, from `package.json`. */
declare const __KLIRR_VERSION__: string;
/** The short commit hash the build was made from (`+dirty` with uncommitted changes). */
declare const __KLIRR_COMMIT__: string;
/** The build date, `YYYY-MM-DD` (UTC). */
declare const __KLIRR_BUILD_DATE__: string;
